"""Разделы 2.6 и 2.7 отчета ЛР1: тренд, сезонность, циклы; сопоставление источников."""
from rep_common import A, H, P, XL, figure, num, pct, table

MRU = ["январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь"]
BOOK = {"A": "A_проверка_таблиц", "B": "B_AI_для_Excel", "C": "C_финмодели"}
TITLE = {"A": "кластер А", "B": "кластер Б", "C": "кластер В"}


GEN = {"январь": "января", "февраль": "февраля", "март": "марта", "апрель": "апреля", "май": "мая", "июнь": "июня", "июль": "июля", "август": "августа", "сентябрь": "сентября", "октябрь": "октября", "ноябрь": "ноября", "декабрь": "декабря"}


def run():
    H(3, "2.6 Тренд, сезонность и деловые циклы")
    P("Оценка устойчивой динамики, сезонности и циклов выполняется по месячным рядам: для кластеров запросов определяются тренд, повторяющиеся месячные пики и отклонения от трендово-сезонного уровня.")
    H(4, "2.6.1 Подготовка рядов")
    P("Для оценки динамики недельные ряды Google Trends приведены к месячным, ряды Вордстата сведены в кластеры. Работа выполнена двумя способами: по Excel-шаблону «тренд, сезонность, деловые циклы» [6] (заполненные рабочие копии лежат в папке Excel) и по расчетной методике в формате Word. Правила подготовки и принятые допущения приведены в таблице [[t:prep]].")
    table("prep", "Правила подготовки рядов и допущения",
          ["Операция", "Правило", "Допущение или ограничение"],
          [["Недели в месяцы", "значение месяца - простое среднее недель, начало которых приходится на этот месяц", "неделя на стыке месяцев относится к месяцу начала"],
           ["Неполные периоды", "исключены первый месяц ряда (ряд начинается 26.09.2021) и последняя неполная неделя", "ряд для расчета: 10.2021-09.2026, 60 месяцев (предел шаблона)"],
           ["Кластер Google Trends", "кластер А - среднее индексов «excel audit» и «spreadsheet audit»; кластер Б - индекс «excel copilot»; кластер В - индекс «financial model audit»", "индексы одиночных запросов нормированы каждый по своему максимуму; кластер усреднен без весов"],
           ["Кластер Вордстата", "сумма запросов кластера по месяцам, Россия: А - проверка формул excel, ошибки в формулах excel, аудит excel, проверить excel на ошибки; Б - нейросеть для excel, excel искусственный интеллект, excel copilot, chatgpt excel; В - проверка финансовой модели, аудит финансовой модели", "фразы запросов частично пересекаются по словоформам, суммирование может давать небольшое двойное счета"],
           ["Нормирование Вордстата", "значение месяца / максимум ряда x 100 (формула шаблона)", "максимум определяется выбросами, поэтому выбросы обработаны заранее"],
           ["Разовые выбросы", "значение, превышающее втрое второе по величине значение ряда, заменяется средним трех предыдущих месяцев; применено один раз: кластер В, 09.2026 (1 069 запросов заменены на 56)", "исходное значение сохранено в журнале выгрузки; всплеск в феврале 2025 г. по «chatgpt excel» (4 388) выбросом не признан (менее чем втрое выше следующего значения кластера Б) и оставлен как событие"],
           ["Территории рядов", "Google Trends - весь мир, Вордстат - Россия", "территории рядов различаются; для проверки построены варианты «только Google Trends» и «только Вордстат»"],
           ["Веса сводного индекса", "0,5 и 0,5 (значение шаблона по умолчанию)", "вес не обоснован отдельно; влияние проверено вариантами с одним источником"]],
          "Таблица фиксирует, какие преобразования выполнены над исходными рядами. Основное ограничение: ряды двух сервисов относятся к разным территориям, поэтому сводный индекс интерпретируется как индекс интереса двух аудиторий (мировой англоязычной и русскоязычной Яндекса), а не как единая территория рынка.")
    H(4, "2.6.2 Расчет по Excel-шаблону")
    names = {"A_проверка_таблиц": "А, оба источника", "A_только_GT": "А, только Google Trends", "A_только_YW": "А, только Вордстат", "B_AI_для_Excel": "Б, оба источника", "C_финмодели": "В, оба источника"}
    order = ["A_проверка_таблиц", "A_только_GT", "A_только_YW", "B_AI_для_Excel", "C_финмодели"]
    def col(code):
        d = XL[code]
        tr, ss_ = d["trend"], d["season_stats"]
        return [num(tr["Количество наблюдений"]), num(tr["Средний индекс за первые 12 месяцев"], 1), num(tr["Средний индекс за последние 12 месяцев"], 1),
                (pct(tr["Относительное изменение"], 0, True) if tr["Относительное изменение"] < 20 else "рост от нулевой базы (первые 12 мес. 0,1)"), tr["Классификация тренда"], num(tr["Наклон линейного тренда"], 2),
                ss_["Оценка силы сезонности"] + ", амплитуда " + num(ss_["Амплитуда сезонности"], 2), ss_["Месяц максимума"] + " / " + ss_["Месяц минимума"],
                num(d["cycles"]["Текущий циклический коэффициент"], 2), d["cycles"]["Текущая фаза"]]
    cols = [col(c) for c in order]
    labels = ["Месяцев в ряду", "Среднее, первые 12 мес.", "Среднее, последние 12 мес.", "Изменение", "Тренд", "Наклон за месяц", "Сезонность", "Максимум / минимум", "Текущий коэффициент", "Фаза"]
    table("xlt", "Результаты расчета по Excel-шаблону (листы «Панель», «Оценка_тренда», «Сезонность», «Деловые_циклы»)",
          ["Показатель"] + [names[c] for c in order],
          [[labels[i]] + [cols[j][i] for j in range(5)] for i in range(len(labels))],
          "Сводный индекс кластеров А, Б и В классифицирован как растущий; по кластеру А тренд определяется Google Trends (плюс 539 % при росте с очень низкого уровня), тогда как по Вордстату тренд стабильный (плюс 12 % к первому году). Сезонность во всех книгах выраженная (амплитуда выше порога 0,30). Текущий месяц (09.2026) по кластеру А находится в норме при обоих источниках (коэффициент 1,01) и ниже тренда по одному Вордстату (0,79); по кластерам Б и В - выше тренда, но для кластера В это следствие малых значений ряда.")
    ss = {c: [r[3] for r in XL[BOOK[c]]["season"]] for c in "ABC"}
    ssy = [r[3] for r in XL["A_только_YW"]["season"]]
    ssg = [r[3] for r in XL["A_только_GT"]["season"]]
    table("season_xlt", "Сезонные индексы по месяцам (лист «Сезонность», 1,00 - средний уровень)",
          ["Месяц", "Кластер А (оба)", "А: только Google Trends", "А: только Вордстат", "Кластер Б", "Кластер В"],
          [[MRU[i], num(ss["A"][i], 2), num(ssg[i], 2), num(ssy[i], 2), num(ss["B"][i], 2), num(ss["C"][i], 2)] for i in range(12)],
          "Сезонность по Вордстату (Россия) однозначна: максимум в октябре-декабре (индекс 1,13-1,39), второй подъем в апреле-мае (1,07-1,11), глубокий спад в июле-августе (0,65-0,66), сентябрь переходный (0,87). Сезонные индексы по Google Trends для кластера А другие (максимум в сентябре-марте, минимум в ноябре-декабре), но ряд Google Trends имеет рост на последнем году, который искажает оценку сезонности. Для кластера Б сезонные индексы ненадежны: история ряда короче трех лет, интерес начался в 2023 г. [6].")
    figure("dyn", "Рисунки/01_динамика_кластеров.png", "Динамика кластеров: Google Trends (мир) и Вордстат (Россия), месячные ряды 10.2021-09.2026",
           "На рисунке показаны месячные значения и скользящая средняя за 12 месяцев. В кластере А интерес Google Trends вырос с 7 до 40-68 пунктов за последние полтора года, а скользящая средняя Вордстата росла до конца 2025 г. и затем снижается. В кластере Б обе средние растут до 2025 г., после чего Вордстат снижается, а Google Trends продолжает рост. Разовый всплеск «chatgpt excel» в феврале 2025 г. виден в кластере Б.")
    figure("seas", "Рисунки/02_сезонные_индексы.png", "Сезонные индексы кластеров по Вордстату (Россия), 100 - среднее значение",
           "Красные столбцы отмечают месяцы с индексом 110 и выше, синие - ниже 90. Для кластеров А и В хорошо видно двойной подъем (осень и весна) и летний спад, который соответствует календарю деловой отчетности и учебного года; причинная связь с календарем является гипотезой и данными поиска не доказывается.")
    figure("cyc", "Рисунки/04_циклический_коэффициент.png", "Циклический коэффициент кластеров по Excel-шаблону (отклонение от тренда с учетом сезонности)",
           "Коэффициент ниже 0,9 означает спрос ниже трендового уровня, выше 1,1 - выше. Кластер А колеблется в узком коридоре 0,88-1,30, кластеры Б и В имеют большие отклонения из-за малой базы начала ряда и выбросов. Коэффициент, рассчитанный по шаблону, использует трейлинговую среднюю за 12 месяцев, поэтому в растущих рядах он систематически выше 1.")
    H(4, "2.6.3 Расчет по методике в формате Word")
    w = A["word"]
    rows = []
    for cl in "ABC":
        for nm, lab in (("GT", "Google Trends, мир"), ("YW_RU", "Вордстат, Россия"), ("YW_BY", "Вордстат, Беларусь")):
            if nm not in w[cl]:
                continue
            d = w[cl][nm]
            rows.append([TITLE[cl], lab, num(d["prev12"], 1), num(d["last12"], 1), "н/д" if d["chg_prev"] is None else pct(d["chg_prev"], 0, True),
                         pct(d["share_up"], 0), "снижение" if (d["chg_prev"] or 0) < -0.15 else ("рост" if (d["chg_prev"] or 0) > 0.15 else "стабильность")])
    table("word_dyn", "Рабочая таблица оценки устойчивой динамики (среднемесячное значение)",
          ["Кластер", "Источник", "Среднее предыдущих 12 мес.", "Среднее последних 12 мес.", "Изменение", "Доля месяцев роста", "Тип динамики"],
          rows,
          "Сравнение последнего года с предыдущим дает иную картину, чем сравнение с первым годом: по Google Trends интерес растет (в кластере А почти в четыре раза, в кластере В в семь-восемь раз), по Вордстату в России в кластерах А и Б снижается на 12-18 % (для кластера Б это в пределах порога стабильности ±15 %, поэтому в таблице 31 он отмечен как стабильность), в Беларуси снижается на 20-59 %. Доля месяцев роста составляет 25-54 %, то есть монотонного тренда нет: рост идет скачками, а в кластерах Вордстата преобладают месяцы снижения.")
    rows = []
    for cl in "ABC":
        for nm, lab in (("GT", "Google Trends"), ("YW_RU", "Вордстат, Россия")):
            d = w[cl][nm]
            rows.append([TITLE[cl], lab, num(d["ma3_last"], 1), num(d["ma12_last"], 1), num(d["ma12_max"], 1), pct(d["ma12_last"] / d["ma12_max"], 0)])
    table("ma", "Скользящие средние на 09.2026",
          ["Кластер", "Источник", "Средняя за 3 мес.", "Средняя за 12 мес.", "Максимум средней за 12 мес.", "Текущая 12-мес. средняя к максимуму"],
          rows,
          "Скользящая средняя за 3 месяца выше средней за 12 месяцев только в кластере А по Google Trends (45,4 против 39,8): краткосрочно интерес растет. В кластерах Б и В по Google Trends она ниже годовой (после пика весны 2026 г.), а по Вордстату во всех кластерах ниже годовой, в том числе из-за летнего сезонного спада, поэтому сопоставление с учетом сезонности выполнено в таблице фаз.")
    rows = []
    for cl in "ABC":
        for nm, lab in (("GT", "Google Trends"), ("YW_RU", "Вордстат, Россия"), ("YW_BY", "Вордстат, Беларусь")):
            if nm not in w[cl]:
                continue
            d = w[cl][nm]
            if nm == "GT" and cl == "B":
                dec = "ряд короче трех лет, вывод не делается"
            else:
                dec = f"запуск продвижения за 1-3 мес. до {GEN.get(d['season_peak'], d['season_peak'])}" if d["peak_repeat"] >= 3 else "повторяемость пика не подтверждена"
            rows.append([TITLE[cl], lab, d["season_peak"], d["season_trough"], num(d["season_amp"], 0), f"{d['peak_repeat']} из 4", dec])
    table("word_season", "Показатели сезонности (метод Word, сезонный индекс = среднее месяца / среднее всех месяцев x 100)",
          ["Кластер", "Источник", "Месяц пика", "Месяц минимума", "Амплитуда, пункты", "Повторяемость пика: лет из 4 (2022-2025), когда месяц пика входит в тройку лучших месяцев года", "Решение для бизнеса"],
          rows,
          "Сезонность подтверждается только там, где пик повторяется несколько лет подряд [6]. По Вордстату в России для кластера А пик (декабрь) повторяется в четырех годах из четырех, минимум приходится на июль, кластер В показывает пик в апреле с повторением в трех годах. Для Google Trends по кластеру А сентябрь входит в тройку лучших месяцев во всех четырех годах, но абсолютный максимум ряда сместился на 2025-2026 гг. из-за роста (ноябрь 2025, май 2026), а по кластерам Б и В пики не повторяются; поэтому сезонное планирование строится по Вордстату, а сентябрьский подъем Google Trends используется как дополнительный сигнал.")
    ya = w["A"]["YW_RU"]
    rows = []
    for i in range(12):
        v = ya["season_idx"][i]
        grade = "пик сезона" if v > 120 else ("повышенный интерес" if v >= 105 else ("средний уровень" if v >= 95 else ("умеренный спрос" if v >= 80 else "низкий сезон")))
        dec = {"пик сезона": "заранее готовить рекламу, посадочные страницы и поддержку", "повышенный интерес": "усиливать продажи, публиковать коммерческие предложения", "средний уровень": "базовый период для сравнения",
               "умеренный спрос": "поддерживать присутствие, собирать аудиторию", "низкий сезон": "сокращать рекламный бюджет, вести подготовительные коммуникации"}[grade]
        mm = ya["series"]
        rows.append([MRU[i].capitalize(), num(sum(mm[j] for j in range(60) if (j + 9) % 12 == i) / 5, 0), num(v, 0), grade, dec])
    def months_where(cond):
        return ", ".join(MRU[i] for i in range(12) if cond(ya["season_idx"][i]))
    season_text = (f"Сезонный профиль кластера А выражен: пик сезона (индекс выше 120) - {months_where(lambda v: v > 120)}; повышенный интерес (105-120) - {months_where(lambda v: 105 <= v <= 120)}; "
                   f"средний уровень - {months_where(lambda v: 95 <= v < 105)}; умеренный спрос (80-95) - {months_where(lambda v: 80 <= v < 95)}; низкий сезон (ниже 80) - {months_where(lambda v: v < 80)}. "
                   "Следовательно, запуск продвижения, тестовой рекламы и публикации контента целесообразно начинать за один-три месяца до осеннего подъема, то есть в августе-сентябре, а июль-август использовать для разработки продукта.")
    table("season12", "Рабочая таблица сезонности: кластер А, Вордстат, Россия (среднемесячное число запросов за 5 лет)",
          ["Месяц", "Среднее значение", "Сезонный индекс", "Оценка месяца", "Решение для бизнеса"],
          rows,
          season_text)
    rows = []
    for cl in "ABC":
        for nm, lab in (("GT", "Google Trends"), ("YW_RU", "Вордстат, Россия"), ("YW_BY", "Вордстат, Беларусь")):
            if nm not in w[cl]:
                continue
            ph = w[cl][nm]["phase"]
            rows.append([TITLE[cl], lab, pct(ph["g6"], 1, True), pct(ph["g12"], 1, True), pct(ph["share"], 0), ph["phase"]])
    def phs(nm):
        return ", ".join(f"{k} - {w[k][nm]['phase']['phase']}" for k in "ABC" if nm in w[k])
    phase_text = f"По результатам: Google Trends (мир): кластеры {phs('GT')}; Вордстат (Россия): {phs('YW_RU')}; Вордстат (Беларусь): {phs('YW_BY')}."
    table("phase", "Фаза цикла по 12-месячной средней сезонно очищенного ряда",
          ["Кластер", "Источник", "Изменение средней за 6 мес.", "Изменение средней за 12 мес.", "Средняя к максимуму", "Фаза"],
          rows,
          "Фаза определена по рабочему правилу (допущение): рост - средняя за 12 месяцев выросла за полгода и за год более чем на 5 %; пик - средняя составляет не менее 95 % максимума и не растет; спад - снизилась за полгода более чем на 5 %; замедление и восстановление - промежуточные состояния. " + phase_text + " Поисковые данные указывают на признаки циклического изменения интереса; деловой цикл рынка такими данными не доказывается и требует подтверждения внешними показателями [6].")
    H(4, "2.6.4 Сверка Python и Excel, особенности шаблона")
    rows = []
    for c in A["xlt_vs_excel"]:
        rows.append([c["book"], f"{c['dG']:.4f}".replace(".", ","), f"{c['dK']:.4f}".replace(".", ","), f"{c['dS']:.5f}".replace(".", ","), f"{c['dChange']:.5f}".replace(".", ","), "да" if c["labels_equal"] else "нет"])
    table("pyxl", "Сверка независимого расчета на Python с результатами Excel",
          ["Книга", "Макс. расхождение сводного индекса", "Макс. расхождение циклического коэффициента", "Макс. расхождение сезонных индексов", "Расхождение изменения", "Метки (тренд, сезонность, фаза) совпали"],
          rows,
          "Расчет шаблона повторен на Python по тем же формулам. Максимальные расхождения не превышают 0,005 пункта индекса и объясняются округлением входных значений до двух знаков при вводе в Excel, классификации тренда, силы сезонности, месяцев максимума и минимума и фазы совпали во всех пяти книгах.")
